//! Design tokens + shared widget styles for the iced UI.
//!
//! Ported from the old GTK `style.css` design language and polished: a
//! consistent spacing scale, soft rounded cards, subtle 1px borders instead of
//! harsh lines, and refined hover/pressed states.
//!
//! Rules for implementers:
//! - Use ONLY these tokens for colors/spacing/radii/type sizes.
//! - Do NOT edit this file. Area-specific style closures (e.g. the red progress
//!   slider) are built in YOUR file from these tokens.

use iced::theme::{Palette, Theme};
use iced::widget::{button, container, scrollable, text_input};
use iced::{Background, Border, Color, Font, Shadow};

// ---------------------------------------------------------------------------
// Color tokens
// ---------------------------------------------------------------------------

const fn c(r: u8, g: u8, b: u8) -> Color {
    Color {
        r: r as f32 / 255.0,
        g: g as f32 / 255.0,
        b: b as f32 / 255.0,
        a: 1.0,
    }
}

const fn ca(r: u8, g: u8, b: u8, a: f32) -> Color {
    Color {
        r: r as f32 / 255.0,
        g: g as f32 / 255.0,
        b: b as f32 / 255.0,
        a,
    }
}

pub const fn white(a: f32) -> Color {
    Color {
        r: 1.0,
        g: 1.0,
        b: 1.0,
        a,
    }
}

