// ---------------------------------------------------------------------------
// Button styles
// ---------------------------------------------------------------------------

fn base_button(bg: Color, text: Color, radius: f32) -> button::Style {
    button::Style {
        background: Some(Background::Color(bg)),
        text_color: text,
        border: Border {
            color: Color::TRANSPARENT,
            width: 0.0,
            radius: radius.into(),
        },
        ..button::Style::default()
    }
}

/// Sidebar nav item ("Home", "Likes", ... and the Settings button).
pub fn nav_item(active: bool) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |_t, status| {
        let (bg, fg) = match (active, status) {
            (true, _) => (ACCENT_BG, ACCENT_FG),
            (false, button::Status::Hovered) => (white(0.06), TEXT),
            (false, button::Status::Pressed) => (ACCENT_BG_FAINT, ACCENT_FG),
            (false, _) => (Color::TRANSPARENT, white(0.45)),
        };
        base_button(bg, fg, RADIUS_MD)
    }
}

/// Circular transparent icon button (transport, like/dislike, repeat, ...).
pub fn icon_button(_t: &Theme, status: button::Status) -> button::Style {
    let bg = match status {
        button::Status::Hovered => white(0.08),
        button::Status::Pressed => ACCENT_BG_FAINT,
        _ => Color::TRANSPARENT,
    };
    let mut style = base_button(bg, TEXT, RADIUS_PILL);
    if matches!(status, button::Status::Disabled) {
        style.text_color = TEXT_GHOST;
    }
    style
}

/// An icon button carrying an "engaged" accent state (active repeat, liked, ...).
pub fn icon_button_active(_t: &Theme, status: button::Status) -> button::Style {
    let bg = match status {
        button::Status::Hovered => ACCENT_BG,
        _ => ACCENT_BG_FAINT,
    };
    base_button(bg, ACCENT_FG, RADIUS_PILL)
}

/// Primary call-to-action ("Connect", "Sign In").
pub fn primary_button(_t: &Theme, status: button::Status) -> button::Style {
    let bg = match status {
        button::Status::Hovered => ca(130, 160, 255, 0.32),
        button::Status::Pressed => ca(130, 160, 255, 0.40),
        button::Status::Disabled => white(0.05),
        _ => ACCENT_BG,
    };
    let mut style = base_button(bg, ACCENT_FG, RADIUS_XL);
    style.border = Border {
        color: ACCENT_BORDER,
        width: 1.0,
        radius: RADIUS_XL.into(),
    };
    if matches!(status, button::Status::Disabled) {
        style.text_color = TEXT_FAINT;
        style.border.color = BORDER_SUBTLE;
    }
    style
}

/// Secondary button ("Dismiss Queue", "Skip", settings secondary actions).
pub fn secondary_button(_t: &Theme, status: button::Status) -> button::Style {
    let bg = match status {
        button::Status::Hovered => white(0.10),
        button::Status::Pressed => ACCENT_BG_FAINT,
        button::Status::Disabled => white(0.03),
        _ => white(0.06),
    };
    let mut style = base_button(bg, TEXT, RADIUS_LG);
    style.border = Border {
        color: BORDER_SUBTLE,
        width: 1.0,
        radius: RADIUS_LG.into(),
    };
    if matches!(status, button::Status::Disabled) {
        style.text_color = TEXT_GHOST;
    }
    style
}

/// `secondary_button` look for a `mouse_area`-driven control (Play All /
/// Shuffle are queue drag sources, so hover is tracked by the view).
pub fn secondary_surface(hovered: bool) -> impl Fn(&Theme) -> container::Style {
    move |_t| container::Style {
        background: Some(Background::Color(if hovered {
            white(0.10)
        } else {
            white(0.06)
        })),
        text_color: Some(TEXT),
        border: Border {
            color: BORDER_SUBTLE,
            width: 1.0,
            radius: RADIUS_LG.into(),
        },
        ..container::Style::default()
    }
}

/// Inline artist link (a padding-less button inside a caption line): the
/// caption colour at rest, bright while hovered/pressed. The underline comes
/// from the rich-text span it wraps.
pub fn link_text(color: Color) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |_t, status| button::Style {
        background: None,
        text_color: match status {
            button::Status::Hovered | button::Status::Pressed => TEXT_BRIGHT,
            _ => color,
        },
        ..button::Style::default()
    }
}

/// Destructive action ("Log out", "Clear cache").
pub fn danger_button(_t: &Theme, status: button::Status) -> button::Style {
    let bg = match status {
        button::Status::Hovered => ca(255, 100, 100, 0.28),
        button::Status::Pressed => ca(255, 100, 100, 0.36),
        button::Status::Disabled => ca(255, 100, 100, 0.06),
        _ => ca(255, 100, 100, 0.16),
    };
    let mut style = base_button(bg, c(255, 200, 200), RADIUS_XL);
    style.border = Border {
        color: ca(255, 100, 100, 0.35),
        width: 1.0,
        radius: RADIUS_XL.into(),
    };
    if matches!(status, button::Status::Disabled) {
        style.text_color = ca(255, 200, 200, 0.4);
        style.border.color = ca(255, 100, 100, 0.15);
    }
    style
}

/// Radio filter chip; `selected` carries the accent fill.
pub fn chip(selected: bool) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |_t, status| {
        let (bg, fg, border) = match (selected, status) {
            (true, _) => (ACCENT_BG, ACCENT_FG, ACCENT_BORDER),
            (false, button::Status::Hovered) => (white(0.08), TEXT, BORDER_SUBTLE),
            (false, _) => (white(0.04), TEXT_DIM, BORDER_SUBTLE),
        };
        let mut style = base_button(bg, fg, RADIUS_PILL);
        style.border = Border {
            color: border,
            width: 1.0,
            radius: RADIUS_PILL.into(),
        };
        style
    }
}

/// Transparent list-row button (track rows, recent items, suggestions);
/// `highlighted` marks the currently-playing row.
pub fn list_row(highlighted: bool) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |_t, status| {
        let bg = match (highlighted, status) {
            (true, _) => ACCENT_BG_FAINT,
            (false, button::Status::Hovered) => white(0.05),
            (false, button::Status::Pressed) => ACCENT_BG_GHOST,
            (false, _) => Color::TRANSPARENT,
        };
        base_button(bg, TEXT, RADIUS_LG)
    }
}

/// Detail-panel tab ("Up Next" / "Lyrics").
pub fn detail_tab(active: bool) -> impl Fn(&Theme, button::Status) -> button::Style {
    move |_t, status| {
        let (bg, fg) = match (active, status) {
            (true, _) => (ACCENT_BG, ACCENT_FG),
            (false, button::Status::Hovered) => (white(0.06), TEXT),
            (false, _) => (Color::TRANSPARENT, TEXT_DIM),
        };
        base_button(bg, fg, RADIUS_PILL)
    }
}

// ---------------------------------------------------------------------------
// Shared content-grid surfaces (one source of truth; GTK `.track-row` /
// `.cover-card` chassis — previously duplicated per view and drifting)
// ---------------------------------------------------------------------------

/// Resting chassis for `mouse_area`-based track/browse rows in the 2-column
/// content grids (GTK `.track-row`): filled rounded card with a 1 px border,
/// brightening + accent border tint on hover.
pub fn row_surface(hovered: bool) -> impl Fn(&Theme) -> container::Style {
    move |_t| container::Style {
        background: Some(Background::Color(if hovered {
            BG_CARD_HOVER
        } else {
            BG_CARD
        })),
        border: Border {
            color: if hovered { ACCENT_BORDER } else { BORDER_CARD },
            width: 1.0,
            radius: RADIUS_LG.into(),
        },
        ..container::Style::default()
    }
}

/// Drag-and-drop role of a content-grid row while a playlist reorder drag is
/// active (see `playlists::row_drop`).
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum RowDrop {
    None,
    /// The row being dragged.
    Lifted,
    /// The row the drag would land on.
    Target,
}

/// [`row_surface`] with the reorder-drag roles layered on top: the lifted row
/// fades, the target row takes a solid accent outline.
pub fn row_surface_drop(hovered: bool, drop: RowDrop) -> impl Fn(&Theme) -> container::Style {
    move |t| match drop {
        RowDrop::None => row_surface(hovered)(t),
        RowDrop::Lifted => container::Style {
            background: Some(Background::Color(ACCENT_BG_GHOST)),
            border: Border {
                color: ACCENT_BORDER,
                width: 1.0,
                radius: RADIUS_LG.into(),
            },
            ..container::Style::default()
        },
        RowDrop::Target => container::Style {
            background: Some(Background::Color(ACCENT_BG_FAINT)),
            border: Border {
                color: ACCENT_SOFT,
                width: 2.0,
                radius: RADIUS_LG.into(),
            },
            ..container::Style::default()
        },
    }
}

/// Button twin of [`row_surface`] for non-draggable rows (artist/channel
/// rows) so a grid mixes button rows and `mouse_area` rows seamlessly.
pub fn row_button(_t: &Theme, status: button::Status) -> button::Style {
    let (bg, border_color) = match status {
        button::Status::Hovered => (BG_CARD_HOVER, ACCENT_BORDER),
        button::Status::Pressed => (ACCENT_BG_GHOST, ACCENT_BORDER),
        _ => (BG_CARD, BORDER_CARD),
    };
    let mut style = base_button(bg, TEXT, RADIUS_LG);
    style.border = Border {
        color: border_color,
        width: 1.0,
        radius: RADIUS_LG.into(),
    };
    style
}

/// Cover-card chassis for `mouse_area`-based 150 px cards (GTK `.cover-card`):
/// transparent at rest, soft tint on hover.
pub fn card_surface(hovered: bool) -> impl Fn(&Theme) -> container::Style {
    move |_t| container::Style {
        background: hovered.then_some(Background::Color(white(0.05))),
        border: Border {
            color: Color::TRANSPARENT,
            width: 0.0,
            radius: RADIUS_CARD.into(),
        },
        ..container::Style::default()
    }
}

// ---------------------------------------------------------------------------
// Scrollbar style (GTK global thin-pill scrollbar: transparent rail, 4 px
// pill slider, brighter/accented while engaged)
// ---------------------------------------------------------------------------

pub fn thin_scrollbar(theme_ref: &Theme, status: scrollable::Status) -> scrollable::Style {
    let mut style = scrollable::default(theme_ref, status);
    let engaged = matches!(
        status,
        scrollable::Status::Hovered { .. } | scrollable::Status::Dragged { .. }
    );
    let rail = scrollable::Rail {
        background: None,
        border: Border {
            color: Color::TRANSPARENT,
            width: 0.0,
            radius: RADIUS_PILL.into(),
        },
        scroller: scrollable::Scroller {
            background: Background::Color(if engaged { ACCENT_BG } else { white(0.12) }),
            border: Border {
                color: Color::TRANSPARENT,
                width: 0.0,
                radius: RADIUS_PILL.into(),
            },
        },
    };
    style.container = container::Style::default();
    style.horizontal_rail = rail;
    style.vertical_rail = rail;
    style
}

// ---------------------------------------------------------------------------
// Text input style
// ---------------------------------------------------------------------------

pub fn entry(_t: &Theme, status: text_input::Status) -> text_input::Style {
    let focused = matches!(status, text_input::Status::Focused { .. });
    text_input::Style {
        background: Background::Color(if focused { BG_ENTRY_FOCUS } else { BG_ENTRY }),
        border: Border {
            color: if focused {
                ACCENT_BORDER
            } else {
                BORDER_SUBTLE
            },
            width: 1.0,
            radius: RADIUS_MD.into(),
        },
        icon: TEXT_DIM,
        placeholder: white(0.25),
        value: TEXT,
        selection: ACCENT_BG,
    }
}
